// Room inventory and low-typing inspection controls, embedded in the standalone HTML.
const roomUiStyle=document.createElement('style');
roomUiStyle.textContent=`.inventory-filters{display:flex;gap:16px;align-items:end;margin-top:22px}.inventory-filters>div{min-width:200px}.inventory-filters label{display:block;font-size:12px;margin-bottom:6px;color:var(--muted)}@media(max-width:760px){.inventory-filters{flex-wrap:wrap}.inventory-filters>div{min-width:150px;flex:1}}.room-card.occupied-room{background:#e8eff6;border-color:#bccbd8}.room-category{display:inline-block;font-size:11px;font-weight:600;padding:4px 8px;border-radius:4px;background:var(--ivory);color:var(--forest)}.occupied-room .room-category{background:#d7e3ee;color:#304e68}.occupied-room .badge{background:#d7e3ee;color:#304e68}.inventory-key{display:flex;gap:16px;align-items:center;flex-wrap:wrap;font-size:12px;color:var(--muted);margin-bottom:16px}.inventory-key span{display:flex;align-items:center;gap:7px}.inventory-key i{width:14px;height:14px;display:inline-block;border:1px solid var(--line);background:var(--surface);border-radius:3px}.inventory-key i.occupied-key{background:#e8eff6;border-color:#bccbd8}.inspection-options{border:0;padding:0;margin:22px 0 12px;min-width:0}.inspection-options legend{font-size:14px;font-weight:600;padding:0;margin-bottom:5px}.inspection-help{font-size:12px;color:var(--muted);margin-bottom:12px}.comment-cards{display:grid;grid-template-columns:1fr 1fr;gap:10px}.comment-card{display:flex;align-items:flex-start;gap:10px;min-height:66px;padding:13px;background:var(--surface);border:1px solid #858d84;border-radius:8px;cursor:pointer;font-size:13px}.comment-card:has(input:checked){background:var(--sage);border-color:var(--forest)}.comment-card input{width:17px;height:17px;min-height:17px;margin:2px 0 0;accent-color:var(--forest);flex-shrink:0}.comment-other{font-size:12px;color:var(--muted);margin:16px 0 20px}.comment-other summary{cursor:pointer;width:fit-content;min-height:32px;padding:5px 0;text-underline-offset:3px}.comment-other summary:focus-visible{outline:3px solid var(--gold);outline-offset:3px}.comment-other[open] summary{margin-bottom:10px}.comment-other textarea{font-size:13px}.inspection-dialog{max-height:calc(100vh - 40px);overflow:auto}@media(max-width:420px){.comment-cards{grid-template-columns:1fr}}`;
document.head.append(roomUiStyle);
let inventoryCategory='all',inventoryAvailability='all';
function inventoryRooms(){const rooms=new Map(roomData.map(r=>[r[0],[...r]]));bookings.filter(b=>['inhouse','departure'].includes(b.kind)).forEach(b=>rooms.set(b.room,[b.room,b.type,'Occupied',b.kind==='departure'?'Occupied · Departure today':'Occupied · Guest in house']));return [...rooms.values()].sort((a,b)=>a[0].localeCompare(b[0],undefined,{numeric:true}))}
renderRooms=function(){const housekeeping=page==='housekeeping';const all=inventoryRooms();const list=housekeeping?all.filter(r=>['108','205','112'].includes(r[0])):all.filter(r=>(inventoryCategory==='all'||r[1]===inventoryCategory)&&(inventoryAvailability==='all'||(inventoryAvailability==='Unoccupied'?r[2]!=='Occupied':inventoryAvailability==='Being prepared'?!['Occupied','Ready for check-in','Maintenance blocked'].includes(r[2]):r[2]===inventoryAvailability)));const occupied=all.filter(r=>r[2]==='Occupied').length;$('#rooms-content').innerHTML=`${housekeeping?'<div class="notice">Only the supervisor or owner can record cleanliness approval after personally inspecting the room.</div>':''}<div class="section-head"><h2>${housekeeping?'Room preparation':all.length+' rooms'}</h2><span class="muted">${housekeeping?'Current work status':occupied+' occupied · '+(all.length-occupied)+' unoccupied'}</span></div>${housekeeping?'':'<div class="inventory-key" aria-label="Room card colours"><span><i class="occupied-key" aria-hidden="true"></i>Occupied</span><span><i aria-hidden="true"></i>Unoccupied · see room status</span><span>Room number order · sample hotel inventory</span></div>'}${housekeeping?'':`<div class="inventory-filters"><div><label for="room-category-filter">Room category</label><select id="room-category-filter"><option value="all">All categories</option>${[...new Set(all.map(r=>r[1]))].sort().map(type=>`<option ${type===inventoryCategory?'selected':''}>${type}</option>`).join('')}</select></div><div><label for="room-availability-filter">Availability</label><select id="room-availability-filter">${[['all','All availability'],['Ready for check-in','Ready for check-in'],['Occupied','Occupied'],['Unoccupied','All unoccupied'],['Being prepared','Being prepared'],['Maintenance blocked','Maintenance blocked']].map(([value,label])=>`<option value="${value}" ${value===inventoryAvailability?'selected':''}>${label}</option>`).join('')}</select></div><button id="clear-room-filters">Clear filters</button></div><p class="role-note" role="status">Showing ${list.length} of ${all.length} rooms</p>`}<div class="room-grid">${list.map(r=>`<article class="room-card ${r[2]==='Occupied'?'occupied-room':''}" aria-label="Room ${r[0]}, ${r[1]}, ${r[2]}"><div class="section-head"><h3 style="margin:0">${r[0]}</h3><span class="room-category">${r[1]}</span></div><p>${r[3]}</p><span class="badge ${r[2].includes('blocked')?'red':r[2].includes('inspection')||r[2]==='Needs attention'?'amber':''}">${r[2]}</span><button data-room="${r[0]}" aria-label="View room ${r[0]} details">View room details</button></article>`).join('')}</div>${!list.length?'<div class="role-empty"><h3>No rooms match these filters</h3><p>Choose another category or availability, or clear the filters.</p></div>':''}`;if(!housekeeping){$('#room-category-filter').onchange=e=>{inventoryCategory=e.target.value;renderRooms();$('#room-category-filter').focus()};$('#room-availability-filter').onchange=e=>{inventoryAvailability=e.target.value;renderRooms();$('#room-availability-filter').focus()};$('#clear-room-filters').onclick=()=>{inventoryCategory='all';inventoryAvailability='all';renderRooms();$('#room-category-filter').focus()}}document.querySelectorAll('[data-room]').forEach(button=>button.onclick=()=>{const r=inventoryRooms().find(r=>r[0]===button.dataset.room);openDialog('Room '+r[0],`<span class="room-category">${r[1]}</span><p style="margin:20px 0">${r[3]}</p><span class="badge ${r[2]==='Maintenance blocked'?'red':''}">${r[2]}</span><p class="role-note">${r[2]==='Occupied'?'A guest currently occupies this room. It is not available for another check-in.':r[2]==='Awaiting inspection'?'Reported completion still requires personal inspection by the supervisor or owner.':r[2]==='Maintenance blocked'?'The maintenance block keeps this room unavailable regardless of cleanliness.':'Room readiness is evaluated separately from reservation and payment status.'}</p>`)});};
const previousWorkDialog=workDialog;
workDialog=function(room){const w=work.find(w=>w.room===room);if(!w||w.state!=='Awaiting inspection'){previousWorkDialog(room);return}if(!['supervisor','owner'].includes(demoRole))return;
openDialog('Room '+room+' · Record inspection',`<p class="muted">${w.type} · ${w.state}</p><p class="role-note">Recording as ${identities[demoRole][0]} · ${identities[demoRole][1]}</p><form id="inspection-form"><div class="field"><label for="inspection-outcome">Inspection outcome</label><select id="inspection-outcome"><option value="Approved clean">Approve as clean</option><option value="Needs attention">Needs attention · request rework</option></select></div><fieldset class="inspection-options"><legend>Quick comments</legend><p class="inspection-help" id="comment-help">Select the findings you personally confirmed.</p><div id="comment-cards" class="comment-cards"></div></fieldset><details class="comment-other" id="comment-other"><summary>Other / add a note</summary><label for="inspection-note">Additional details</label><textarea id="inspection-note" rows="3" placeholder="Describe a special case"></textarea></details><div class="check"><input id="inspection-confirm" type="checkbox" required><label for="inspection-confirm">I personally inspected this room and this outcome reflects what I found.</label></div><p class="inspection-help" style="margin-top:14px" id="inspection-guidance">Choose a comment or add a note, then confirm your inspection.</p><div class="dialog-actions"><button class="primary" id="record-inspection" disabled>Record inspection</button></div></form>`);
$('#modal').classList.add('inspection-dialog');
const choices={'Approved clean':['Room clean; no issues found','Fresh linen checked','Bathroom checked','Supplies checked'],'Needs attention':['Floor needs cleaning','Linen needs replacing','Bathroom needs cleaning','Supplies need restocking']};
function selectedComments(){return [...document.querySelectorAll('[name="inspection-comment"]:checked')].map(el=>el.value)}
function updateSave(){const hasNote=selectedComments().length>0||$('#inspection-note').value.trim().length>0;$('#record-inspection').disabled=!hasNote||!$('#inspection-confirm').checked}
function drawChoices(){const values=choices[$('#inspection-outcome').value];$('#comment-cards').innerHTML=values.map(value=>`<label class="comment-card"><input name="inspection-comment" type="checkbox" value="${value}" aria-describedby="comment-help"><span>${value}</span></label>`).join('');document.querySelectorAll('[name="inspection-comment"]').forEach(el=>el.onchange=updateSave);updateSave()}
$('#inspection-outcome').onchange=()=>{$('#inspection-note').value='';$('#inspection-confirm').checked=false;$('#comment-other').open=false;drawChoices()};$('#inspection-note').oninput=updateSave;$('#inspection-confirm').onchange=updateSave;drawChoices();
$('#inspection-form').onsubmit=e=>{e.preventDefault();const notes=selectedComments();const custom=$('#inspection-note').value.trim();if(custom)notes.push(custom);if(!notes.length||!$('#inspection-confirm').checked)return;const outcome=$('#inspection-outcome').value,note=notes.join('; ');w.state=outcome;w.note=note+' · '+identities[demoRole][0];const r=roomData.find(r=>r[0]===room);r[2]=outcome==='Approved clean'?'Ready for check-in':outcome;r[3]=outcome==='Approved clean'?'Vacant · Approved clean':'Vacant · '+outcome;const b=bookings.find(b=>b.room===room&&b.kind==='arrival');if(b)b.state=outcome==='Approved clean'?(b.paid?'Ready for check-in':'Payment to verify'):outcome;eventRecord('Room '+room+': '+outcome+'. '+note);syncOccupancy();if(room==='108')$('.timeline').lastElementChild.innerHTML='<strong>'+(outcome==='Approved clean'?'Room ready for check-in':'Preparing for your arrival')+'</strong><small>'+(outcome==='Approved clean'?'Reception will guide you through the arrival procedure.':'The hotel is preparing your room. Reception will confirm when it is ready.')+'</small>';$('#modal').close();renderRole();notify('Room '+room+' updated · attributed to '+identities[demoRole][0])};
};
$('#modal').addEventListener('close',()=>$('#modal').classList.remove('inspection-dialog'));
